def pages_with_direct_ops() -> dict[str, dict]:
    return {k: v for k, v in PAGES.items() if v["direct_ops"]}

def pages_with_buttons() -> dict[str, dict]:
    return {k: v for k, v in PAGES.items() if v["buttons"]}

def pages_with_drag() -> dict[str, dict]:
    return {k: v for k, v in PAGES.items() if v["has_drag"]}

def backend_contract_of(op: str) -> dict | None:
    for v in PAGES.values():
        hit = v.get("direct_ops_backend", {}).get(op)
        if hit:
            return {"op": op, "backend": hit}
    return None

